package org.slavicmyths.hellqa;
import java.util.*;import java.nio.file.*;import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.gametest.framework.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.*;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;import net.neoforged.neoforge.gametest.*;import org.slavicmyths.nethersmithing.*;import org.slavicmyths.infernalfurnace.*;import org.slavicmyths.rpg.Runes;
@GameTestHolder("slavicmyths_hellqa") @PrefixGameTestTemplate(false)
public final class HellQaTests {
 static final class Connection extends net.minecraft.network.Connection {private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public io.netty.channel.Channel channel(){return channel;}}
 static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener l){}}
 static ServerPlayer player(GameTestHelper t){var p=new ServerPlayer(t.getLevel().getServer(),t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"HellFixture"),ClientInformation.createDefault());p.connection=new Listener(p);p.setNoGravity(true);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(t.absoluteVec(new Vec3(3,2,3)));p.setYRot(0);p.setXRot(0);return p;}
 static ItemStack item(String n){return new ItemStack(BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("slavicmyths",n)));}
 static void check(boolean b,String m){if(!b)throw new GameTestAssertException(m);}
 @GameTest(template="empty") public static void productionJarRegistryRecipes(GameTestHelper t)throws Exception{
  System.out.println("HELLQA_WORLD seed="+t.getLevel().getSeed()+" dimension="+t.getLevel().dimension().location()+" origin="+t.absolutePos(BlockPos.ZERO));
  Path actual=net.neoforged.fml.ModList.get().getModFileById("slavicmyths").getFile().getFilePath(),expected=Path.of(System.getProperty("hellqa.expectedJar"));check(Files.isRegularFile(actual)&&Arrays.equals(Files.readAllBytes(actual),Files.readAllBytes(expected)),"Wrong production JAR loaded: "+actual);
  for(String id:NetherArmorRules.IDS){var s=item(id);check(s.getItem() instanceof NetherArmor.Piece,"Armor registry "+id);check(Runes.capacity(s)==NetherArmorRules.sockets(((NetherArmor.Piece)s.getItem()).king,((ArmorItem)s.getItem()).getType()),"Armor sockets "+id);check(org.slavicmyths.registry.ModItemGroup.category(s.getItem())==5,"Armor Creative "+id);}
  for(String id:NetherWeaponRules.IDS){var s=item(id);check(NetherWeapons.owns(s)&&Runes.capacity(s)==2&&!Runes.category(s).isEmpty(),"Weapon registry/category/sockets "+id);check(org.slavicmyths.registry.ModItemGroup.category(s.getItem())==9,"Weapon Creative "+id);}
  for(String id:List.of("infernal_furnace","infernal_coal","nether_aura_amulet"))check(!item(id).isEmpty(),"Missing "+id);
  var recipe=t.getLevel().getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("slavicmyths","ashen_greatsword")).orElseThrow().value();var base=new ItemStack(Items.DIAMOND_SWORD);base.setDamageValue(100);base.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("kept"));org.slavicmyths.item.ItemState.runes(base,2,List.of("heat"));var input=new SmithingRecipeInput(item("nether_hardening_template"),base,item("ashen_blade_core"));check(((SmithingTransformRecipe)recipe).matches(input,t.getLevel()),"Exact transform rejected");var output=((SmithingTransformRecipe)recipe).assemble(input,t.getLevel().registryAccess());check(output.is(item("ashen_greatsword").getItem())&&output.getHoverName().getString().equals("kept")&&Runes.slots(output)==2&&output.getDamageValue()==Math.ceil(100D/base.getMaxDamage()*1950),"Smithing components/wear mixin");
  System.out.println("HELLQA_PASS production JAR="+actual+" registry/socket/creative/actual smithing assemble");t.succeed();
 }
 @GameTest(template="empty") public static void furnaceFuelSmeltNbt(GameTestHelper t){
  var w=t.getLevel();var pos=t.absolutePos(new BlockPos(2,2,2));w.setBlock(pos,InfernalFurnace.BLOCK.get().defaultBlockState(),3);var tile=(InfernalFurnaceTile)w.getBlockEntity(pos);check(tile!=null,"No real furnace block entity");var p=player(t);var menu=new InfernalFurnaceMenu(5,p.getInventory(),tile,new net.minecraft.world.inventory.SimpleContainerData(4));
  for(Item wrong:List.of(Items.COAL,Items.CHARCOAL,Items.LAVA_BUCKET,Items.BLAZE_ROD,Items.BUCKET)){var s=new ItemStack(wrong);check(!tile.canPlaceItem(1,s)&&!menu.slots.get(1).mayPlace(s),"Wrong fuel accepted "+wrong);var side=new net.neoforged.neoforge.items.wrapper.SidedInvWrapper(tile,Direction.NORTH);check(side.insertItem(0,s,false).getCount()==1,"Hopper bypass fuel");}
  tile.setItem(0,new ItemStack(Items.RAW_IRON,64));tile.setItem(1,new ItemStack(Items.COAL));for(int i=0;i<100;i++)InfernalFurnaceTile.tick(w,pos,w.getBlockState(pos),tile);check(tile.getItem(2).isEmpty()&&tile.getItem(0).getCount()==64,"Foreign fuel burned");tile.setItem(1,new ItemStack(InfernalFurnace.COAL.get(),4));for(int i=0;i<100;i++)InfernalFurnaceTile.tick(w,pos,w.getBlockState(pos),tile);check(tile.getItem(2).is(Items.IRON_INGOT)&&tile.getItem(2).getCount()==1&&tile.getItem(0).getCount()==63,"Real smelt2x failed");
  var saved=tile.saveWithFullMetadata(w.registryAccess());var restored=new InfernalFurnaceTile(pos,w.getBlockState(pos));restored.setLevel(w);restored.loadWithComponents(saved,w.registryAccess());check(restored.getItem(0).getCount()==63&&restored.getItem(2).getCount()==1&&restored.saveWithFullMetadata(w.registryAccess()).getShort("BurnTime")==saved.getShort("BurnTime"),"Native furnace NBT lost state");
  tile.setItem(2,new ItemStack(Items.IRON_INGOT,64));for(int i=0;i<200;i++)InfernalFurnaceTile.tick(w,pos,w.getBlockState(pos),tile);check(tile.getItem(0).getCount()==63&&tile.getItem(2).getCount()==64,"Blocked output dupe/consumption");w.removeBlock(pos,false);System.out.println("HELLQA_PASS real furnace: rejected5 fuels/menu/hopper, actual smelt/blocked-output/NBT");t.succeed();
 }
 @GameTest(template="empty") public static void armorAndSkillGuards(GameTestHelper t){
  var p=player(t);p.setItemSlot(EquipmentSlot.HEAD,item("infernal_crown_helmet"));p.setItemSlot(EquipmentSlot.CHEST,item("infernal_king_cuirass"));p.setItemSlot(EquipmentSlot.LEGS,item("infernal_king_leggings"));p.setItemSlot(EquipmentSlot.FEET,item("infernal_king_boots"));p.doTick();NetherArmorEffects.refresh(p);check(Math.abs(p.getMaxHealth()-35)<.001,"Royal HP missing or doubled: "+p.getMaxHealth());check(Math.abs(p.getAttributeValue(Attributes.MOVEMENT_SPEED)-.12)<.0001,"Royal speed must total20%: "+p.getAttributeValue(Attributes.MOVEMENT_SPEED));for(var slot:List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET))p.setItemSlot(slot,ItemStack.EMPTY);p.doTick();NetherArmorEffects.refresh(p);check(p.getMaxHealth()==20&&Math.abs(p.getAttributeValue(Attributes.MOVEMENT_SPEED)-.1)<.0001,"Unequip leaked modifiers");
  var target=EntityType.COW.create(t.getLevel());target.setNoAi(true);target.setNoGravity(true);target.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);target.setHealth(200);target.moveTo(p.getX(),p.getY()+.5,p.getZ()+3);t.getLevel().addFreshEntity(target);var spear=item("navya_ostroga");p.setItemInHand(InteractionHand.MAIN_HAND,spear);NetherSkills.release(p,spear,"navya_ostroga",9);check(target.getHealth()==200,"Undercharge damaged target");NetherSkills.release(p,spear,"navya_ostroga",10);check(target.getHealth()==187&&spear.getDamageValue()==4,"Thrust raw/wear "+target.getHealth());target.invulnerableTime=0;NetherSkills.release(p,spear,"navya_ostroga",10);check(target.getHealth()==187&&!NetherSkills.ready(p,spear.copy(),"navya_ostroga"),"Cooldown swap/release bypass");
  var sword=item("ashen_greatsword");p.setItemInHand(InteractionHand.MAIN_HAND,sword);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.TORCH));NetherSkills.release(p,sword,"ashen_greatsword",16);check(target.getHealth()==187&&NetherSkills.ready(p,sword,"ashen_greatsword"),"Offhand guard failed");p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);NetherSkills.release(p,sword,"ashen_greatsword",16);check(target.getHealth()==169,"Greatsword arc raw");target.discard();System.out.println("HELLQA_PASS real armor equip/unequip HP/speed and charged skill/copy-CD/offhand guards");t.succeed();
 }
}
